mapper.select:
select m.MESSAGEID,m.MSGTITLE,m.URL,m.FROMUSER,m.TOUSER,m.SENDTIME,m.STATE,m.OPERATETIME, m.OPERATESTATE,m.SYNCSTATE,m.BUSINESSID,m.MESSAGETYPE,m.SERVICEID,m.SERVICESTATE,m.SERVICEUPDATATIME, u.username as FROMUSERNAME from CF_MESSAGE m left join cf_users u on m.FROMUSER=u.userid where OPERATESTATE <> 'D' and m.TOUSER=#{userId}
and m.state=#{state}
and m.MSGTITLE like concat('%',#{title},'%')
order by m.sendtime desc

mapper.update:
update CF_MESSAGE set OPERATESTATE='D',OPERATETIME=sysdate,SYNCSTATE='N' where 1=1
and OPERATESTATE  <>  'D'
and businessId=#{businessId}

    and messageType=#{messageType}
